#include <psx/non_normal/protocol.hpp>
#include <bit>
#include <cmath>
#include <algorithm>
#include <limits>
namespace psx::non_normal {namespace {
struct Cursor {std::uint8_t* p;void u32(std::uint32_t n){for(unsigned i=0;i<4;++i)*p++=static_cast<std::uint8_t>(n>>(i*8));}void u64(std::uint64_t n){for(unsigned i=0;i<8;++i)*p++=static_cast<std::uint8_t>(n>>(i*8));}void real(double v){u64(std::bit_cast<std::uint64_t>(v));}void identity(ProcessIdentity i){u32(i.pid);u64(i.creation_filetime);}};
struct Reader {const std::uint8_t* p;std::uint32_t u32(){std::uint32_t n{};for(unsigned i=0;i<4;++i)n|=std::uint32_t(*p++)<<(i*8);return n;}std::uint64_t u64(){std::uint64_t n{};for(unsigned i=0;i<8;++i)n|=std::uint64_t(*p++)<<(i*8);return n;}double real(){return std::bit_cast<double>(u64());}ProcessIdentity identity(){ProcessIdentity i;i.pid=u32();i.creation_filetime=u64();return i;}};
bool id(ProcessIdentity p){return p.pid&&p.creation_filetime;}
bool label(const std::array<char,8>& s){bool ended=false;for(char c:s){if(!c){ended=true;continue;}if(ended||!((c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='-'))return false;}return ended;}
void header(Frame& f,Kind kind,std::size_t n,std::uint32_t sequence,std::uint16_t wire){f={};f.size=16+n;f.bytes[0]='P';f.bytes[1]='C';f.bytes[2]='N';f.bytes[3]='1';f.bytes[4]=static_cast<std::uint8_t>(wire);f.bytes[6]=static_cast<std::uint8_t>(kind);Cursor c{f.bytes.data()+8};c.u32(static_cast<std::uint32_t>(n));c.u32(sequence);}
bool check(std::span<const std::uint8_t> b,Kind k,std::size_t n,std::uint32_t& s){if(b.size()!=16+n||b[0]!='P'||b[1]!='C'||b[2]!='N'||b[3]!='1'||(b[4]!=version&&b[4]!=actor_version)||b[5]||b[6]!=static_cast<std::uint8_t>(k)||b[7])return false;Reader r{b.data()+8};if(r.u32()!=n)return false;s=r.u32();return s!=0;}
}
bool valid(const Request& r)noexcept {
 if((r.wire_version!=version&&r.wire_version!=actor_version)||static_cast<unsigned>(r.command)>4||!id(r.client)||!id(r.target)||!r.session||!r.request||!r.frequency||r.frequency>std::uint64_t(INT64_MAX)/5||r.issued_qpc<0||r.deadline_qpc<=r.issued_qpc||r.deadline_qpc-r.issued_qpc>static_cast<std::int64_t>(r.frequency*5))return false;
 if(!std::isfinite(r.latitude_deg)||!std::isfinite(r.longitude_deg)||!std::isfinite(r.heading_deg)||std::abs(r.latitude_deg)>90||std::abs(r.longitude_deg)>180||r.heading_deg<0||r.heading_deg>=360||!label(r.airport)||!label(r.runway))return false;
 if(r.wire_version==version&&(r.runway_elevation_valid||r.runway_elevation_ft))return false;
 if(r.wire_version==actor_version&&r.command==Command::place_actor&&!r.runway_elevation_valid)return false;
 if(r.command!=Command::place_actor&&(r.runway_elevation_valid||r.runway_elevation_ft))return false;
 return r.command!=Command::place_actor||(id(r.psx)&&r.database_revision&&r.airport[0]&&r.runway[0]);
}
bool valid(const Result& r)noexcept {
 if((r.wire_version!=version&&r.wire_version!=actor_version)||!id(r.server)||!r.session||!r.request||static_cast<unsigned>(r.command)>4||static_cast<unsigned>(r.phase)>7||static_cast<unsigned>(r.reason)>14||(r.capabilities&~3u)||r.observed_qpc<0)return false;
 return std::isfinite(r.latitude_deg)&&std::abs(r.latitude_deg)<=90&&std::isfinite(r.longitude_deg)&&std::abs(r.longitude_deg)<=180&&std::isfinite(r.altitude_m)&&std::isfinite(r.heading_deg)&&r.heading_deg>=0&&r.heading_deg<360&&std::isfinite(r.pitch_deg)&&std::isfinite(r.bank_deg);
}
bool encode(const Request& r,std::uint32_t sequence,Frame& f)noexcept {if(!sequence||!valid(r))return false;header(f,Kind::request,r.wire_version==actor_version?actor_request_bytes:request_bytes,sequence,r.wire_version);Cursor c{f.bytes.data()+16};c.u32(static_cast<std::uint32_t>(r.command));c.identity(r.client);c.identity(r.target);c.u64(r.session);c.u64(r.request);c.u64(r.frequency);c.u64(static_cast<std::uint64_t>(r.issued_qpc));c.u64(static_cast<std::uint64_t>(r.deadline_qpc));c.u64(r.expected_revision);c.u64(r.database_revision);c.real(r.latitude_deg);c.real(r.longitude_deg);c.real(r.heading_deg);for(char v:r.airport)*c.p++=static_cast<std::uint8_t>(v);for(char v:r.runway)*c.p++=static_cast<std::uint8_t>(v);c.identity(r.originator);c.u64(r.originator_session);c.identity(r.psx);c.u32(0);if(r.wire_version==actor_version){const auto ft=std::bit_cast<std::uint16_t>(r.runway_elevation_ft);*c.p++=static_cast<std::uint8_t>(ft);*c.p++=static_cast<std::uint8_t>(ft>>8);*c.p++=r.runway_elevation_valid?1:0;*c.p++=0;}return true;}
bool encode(const Result& r,std::uint32_t sequence,Frame& f)noexcept {if(!sequence||!valid(r))return false;header(f,Kind::result,result_bytes,sequence,r.wire_version);Cursor c{f.bytes.data()+16};c.identity(r.server);c.u64(r.session);c.u64(r.request);c.u32(static_cast<std::uint32_t>(r.command));c.u32(static_cast<std::uint32_t>(r.phase));c.u32(static_cast<std::uint32_t>(r.reason));c.u32(r.capabilities);c.u64(r.revision);c.u64(r.scenery_generation);c.u64(r.resource_generation);c.u64(static_cast<std::uint64_t>(r.observed_qpc));c.real(r.latitude_deg);c.real(r.longitude_deg);c.real(r.altitude_m);c.real(r.heading_deg);c.real(r.pitch_deg);c.real(r.bank_deg);return true;}
bool decode(std::span<const std::uint8_t> b,Request& r,std::uint32_t& s)noexcept {if(b.size()<header_bytes)return false;const auto wire=b[4];if(!check(b,Kind::request,wire==actor_version?actor_request_bytes:request_bytes,s))return false;Request v;v.wire_version=wire;Reader c{b.data()+16};v.command=static_cast<Command>(c.u32());v.client=c.identity();v.target=c.identity();v.session=c.u64();v.request=c.u64();v.frequency=c.u64();v.issued_qpc=static_cast<std::int64_t>(c.u64());v.deadline_qpc=static_cast<std::int64_t>(c.u64());v.expected_revision=c.u64();v.database_revision=c.u64();v.latitude_deg=c.real();v.longitude_deg=c.real();v.heading_deg=c.real();for(char& x:v.airport)x=static_cast<char>(*c.p++);for(char& x:v.runway)x=static_cast<char>(*c.p++);v.originator=c.identity();v.originator_session=c.u64();v.psx=c.identity();if(c.u32())return false;if(wire==actor_version){const auto ft=std::uint16_t(c.p[0])|(std::uint16_t(c.p[1])<<8);v.runway_elevation_ft=std::bit_cast<std::int16_t>(static_cast<std::uint16_t>(ft));const auto flags=std::uint16_t(c.p[2])|(std::uint16_t(c.p[3])<<8);if(flags&~1u)return false;v.runway_elevation_valid=(flags&1u)!=0;c.p+=4;}while(c.p!=b.data()+b.size())if(*c.p++)return false;if(!valid(v))return false;r=v;return true;}
bool decode(std::span<const std::uint8_t> b,Result& r,std::uint32_t& s)noexcept {if(!check(b,Kind::result,result_bytes,s))return false;Result v;v.wire_version=b[4];Reader c{b.data()+16};v.server=c.identity();v.session=c.u64();v.request=c.u64();v.command=static_cast<Command>(c.u32());v.phase=static_cast<Phase>(c.u32());v.reason=static_cast<Reason>(c.u32());v.capabilities=c.u32();v.revision=c.u64();v.scenery_generation=c.u64();v.resource_generation=c.u64();v.observed_qpc=static_cast<std::int64_t>(c.u64());v.latitude_deg=c.real();v.longitude_deg=c.real();v.altitude_m=c.real();v.heading_deg=c.real();v.pitch_deg=c.real();v.bank_deg=c.real();while(c.p!=b.data()+b.size())if(*c.p++)return false;if(!valid(v))return false;r=v;return true;}
}
